            if (prim.isBoolean()){
                result.put(entry.getKey(), prim.getAsBoolean());
            } else if (prim.isNumber()){
                result.put(entry.getKey(), prim.getAsNumber());
            } else if (prim.isString()){
                result.put(entry.getKey(), prim.getAsString());
